window.__votdWeek && window.__votdWeek({"week":"2028-07-03","reading":"Alma 23–29","days":[{"d":"2028-07-03","ref":"Alma 24:27","b":"Alma","c":24,"v":27,"he":"וְלֹא נֶהֱרַג אִישׁ רָשָׁע בֵּינֵיהֶם אַךְ הוּבְאוּ יוֹתֵר מֵאֶלֶף לָדַעַת אֶת־הָאֱמֶת וְכֵן רָאִינוּ כִּי עֹשֶׂה יְהוָה בִּדְרָכִים רַבּוֹת לִישׁוּעַת עַמּוֹ׃","en":"And there was not a wicked man slain among them; but there were more than a thousand brought to the knowledge of the truth; thus we see that the Lord worketh in many ways to the salvation of his people."},{"d":"2028-07-04","ref":"Alma 26:8","b":"Alma","c":26,"v":8,"he":"בָּרוּךְ שֵׁם אֱלֹהֵינוּ נְזַמְּרָה לִתְהִלָּתוֹ אַף נוֹדֶה לִשְׁמוֹ הַקָּדוֹשׁ כִּי פֹּעֵל צֶדֶק הוּא לְעוֹלָם׃","en":"Blessed be the name of our God; let us sing to his praise, yea, let us give thanks to his holy name, for he doth work righteousness forever."},{"d":"2028-07-05","ref":"Alma 26:11","b":"Alma","c":26,"v":11,"he":"וַיֹּאמֶר אֵלָיו עַמּוֹן לֹא בְכֹחִי וְלֹא בְחׇכְמָתִי אֶתְהַלֵּל אַךְ הִנֵּה מָלְאָה שִׂמְחָתִי אַף רָוָה לִבִּי שִׂמְחָה וְאֶשְׂמַח בֵּאלֹהָי׃","en":"But Ammon said unto him: I do not boast in my own strength, nor in my own wisdom; but behold, my joy is full, yea, my heart is brim with joy, and I will rejoice in my God."},{"d":"2028-07-06","ref":"Alma 27:10","b":"Alma","c":27,"v":10,"he":"וַיֹּאמֶר הַמֶּלֶךְ אֵלָיו דְּרָשׁ נָא בַּיהוָה וְאִם־יֹאמַר אֵלֵינוּ לְכוּ וְנֵלֵכָה וְאִם־לֹא נֹאבַד בָּאָרֶץ׃","en":"But the king said unto him: Inquire of the Lord, and if he saith unto us go, we will go; otherwise we will perish in the land."},{"d":"2028-07-07","ref":"Alma 27:17","b":"Alma","c":27,"v":17,"he":"וַתִּגְדַּל שִׂמְחַת עַמּוֹן עַד־מְאֹד עַד־כִּי מָלְאָה נַפְשׁוֹ אַף נִבְלַע בְּשִׂמְחַת אֱלֹהָיו עַד־כְּלוֹת כֹּחוֹ וַיִּפֹּל שֵׁנִית אָרְצָה׃","en":"Now the joy of Ammon was so great even that he was full; yea, he was swallowed up in the joy of his God, even to the exhausting of his strength; and he fell again to the earth."},{"d":"2028-07-08","ref":"Alma 29:1","b":"Alma","c":29,"v":1,"he":"מִי־יִתֵּן וְהָיִיתִי מַלְאָךְ וִיהִי־לִי חֵפֶץ לְבָבִי וְאֵצְאָה וַאֲדַבְּרָה בְּשׁוֹפַר אֱלֹהִים בְּקוֹל מַרְעִישׁ אָרֶץ וְאֶקְרְאָה תְּשׁוּבָה לְכׇל הָעַמִּים׃","en":"O that I were an angel, and could have the wish of mine heart, that I might go forth and speak with the trump of God, with a voice to shake the earth, and cry repentance unto every people!"},{"d":"2028-07-09","ref":"Alma 29:12","b":"Alma","c":29,"v":12,"he":"הֵן זָכַרְתִּי תָמִיד אֶת־שִׁבְיַת אֲבוֹתַי וְהָאֱלֹהִים הַהוּא אֲשֶׁר הִצִּילָם מִיַּד מִצְרַיִם הוּא הִצִּילָם מֵעַבְדוּת׃","en":"Yea, I have always remembered the captivity of my fathers; and that same God who delivered them out of the hands of the Egyptians did deliver them out of bondage."}]});
